import { normalizeDataResponseMetadata } from "./response-metadata.js";
export function validateDataResult(value, hookName) {
    const fail = () => {
        throw new TypeError(`${hookName} must return a valid data result object`);
    };
    if (value === null || typeof value !== "object" || Array.isArray(value))
        return fail();
    const result = value;
    const props = result.props;
    const redirect = result.redirect;
    const notFound = result.notFound;
    const revalidate = result.revalidate;
    const responseMetadata = normalizeDataResponseMetadata(result, hookName);
    let redirectDestination;
    let redirectPermanent;
    if (redirect !== undefined &&
        (redirect === null || typeof redirect !== "object" || Array.isArray(redirect))) {
        return fail();
    }
    if (redirect !== undefined) {
        const redirectRecord = redirect;
        if (typeof redirectRecord.destination !== "string" ||
            (redirectRecord.permanent !== undefined && typeof redirectRecord.permanent !== "boolean"))
            return fail();
        redirectDestination = redirectRecord.destination;
        redirectPermanent = redirectRecord.permanent;
    }
    if (notFound !== undefined && typeof notFound !== "boolean")
        return fail();
    const normalized = {};
    if (redirectDestination !== undefined) {
        normalized.redirect = {
            destination: redirectDestination,
            ...(redirectPermanent !== undefined ? { permanent: redirectPermanent } : {}),
        };
    }
    else if (notFound === true) {
        normalized.notFound = true;
    }
    else {
        if (revalidate !== undefined && revalidate !== false &&
            (typeof revalidate !== "number" || !Number.isFinite(revalidate) || revalidate < 0))
            return fail();
        if (props !== undefined)
            normalized.props = props;
        if (notFound !== undefined)
            normalized.notFound = notFound;
        if (revalidate !== undefined)
            normalized.revalidate = revalidate;
    }
    if (responseMetadata.headers)
        normalized.headers = responseMetadata.headers;
    if (responseMetadata.cookies)
        normalized.cookies = responseMetadata.cookies;
    return normalized;
}
